import logging
from functools import partial
import taf.internal.robot_typecasts as robot_typecasts
from taf.internal.managedobject import ManagedObject


class Node(ManagedObject):

    def __init__(self, config, executor, **kwargs):
        super().__init__(**kwargs)
        self._config = config
        self.add_prerequisite(executor)
        self._executor = executor
        self._setup_script_commands(config)

    def _setup_script_commands(self, config):
        if 'script_paths' in config.keys() and config.script_paths:
            for script_name in config.script_paths:
                logging.info(f"{self._config.type} node mapping {script_name} with yaml command")
                if not config.script_paths[script_name].strip():
                    continue
                script_func = partial(self.execute, script_name)
                self.__setattr__(script_name, script_func)

    def execute(self, script_name, expect_regex='', timeout=30):
        timeout_s = robot_typecasts.time_to_seconds(timeout)
        script_cmd = self._config.script_paths[script_name]
        logging.info(f"{self._config.type} node execute {script_name}: {script_cmd}")
        return self._executor.execute(script_cmd, expect_regex, timeout_s)

    def read_persist_channel(self, expect_regex, timeout):
        return self._executor.read_persist_channel(expect_regex, timeout)

    def execute_script_cmd(self, script_cmd, expect_regex, timeout):
        logging.info(f"{self._config.type} node execute {script_cmd}")
        return self._executor.execute(script_cmd, expect_regex, timeout)

    def upload_file(self, local_file, remote_file):
        return self._executor.upload_file(local_file, remote_file)

    def download_file(self, remote_file, local_file):
        return self._executor.download_file(remote_file, local_file)
